import pytest
from cart import total


def test_total_of_empty_basket_is_zero():
    assert total([]) == 0


def test_total_rejects_a_negative_price():
    with pytest.raises(ValueError):
        total([5, -1])


def test_total_rounds_to_pence():
    assert total([0.1, 0.2]) == 0.3

